import { useEffect } from 'react';
import { useDispatch, useSelector } from 'react-redux';

import { commonActions } from 'app/services/CommonService';
import { selectSettings } from 'app/services/SettingsService';

import { loadSound } from '..';

export const useTimbre = () => {
  const dispatch = useDispatch();
  const { timbre } = useSelector(selectSettings);
  // TODO: choose all the timbres. not only mp3

  useEffect(() => {
    loadSound('drums');
  }, []);

  useEffect(() => {
    let active = true;
    dispatch(commonActions.setLoading(true));
    loadSound((timbre as any).title || timbre)
      .then(() => {
        if (!active) return;
        dispatch(commonActions.setLoading(false));
      })
      .catch(() => {
        if (active) dispatch(commonActions.setLoading(false));
      });
    return () => {
      active = false;
    };
  }, [dispatch, timbre]);
};
