import { useEffect, useRef, useState } from 'react';
import { Helmet } from 'react-helmet-async';
import { useSelector } from 'react-redux';
import styled from 'styled-components';

import {
  Chord,
  ChordQuality,
  KeyMode,
  chordQualities,
  chordSymbol,
  chordTones,
  chordVoicing,
  circleOfFifths,
  detectChords,
  diatonicChords,
  formatPitch,
  pitchClass,
} from 'app/services/ChordsService';
import { useChordPreview } from 'app/services/ChordsService/useChordPreview';
import {
  applicatures,
  keyboardButtons,
  useKeyboardInput,
} from 'app/services/KeyboardService';
import { Note, selectSoundingNotes } from 'app/services/NotesService';
import { chromaticNotes } from 'app/services/NotesService/chromaticNotes';
import { selectSettings } from 'app/services/SettingsService';
import {
  fixedNotesFor,
  timbresLinks,
} from 'app/services/SynthesizerService/timbres';

import { ChordAudioInput } from 'app/components/Chords/ChordAudioInput';
import { CircleOfFifths } from 'app/components/Chords/CircleOfFifths';
import { GuitarFingerings } from 'app/components/Chords/GuitarFingerings';
import { HarmonyExplorer } from 'app/components/Chords/HarmonyExplorer';
import { PianoKey } from 'app/components/Piano/PianoKey';
import { PageWrapper } from 'app/components/_styled/PageWrapper';

export const ChordsPage = () => {
  const [keyIndex, setKeyIndex] = useState(0);
  const [mode, setMode] = useState<KeyMode>('major');
  const [chord, setChord] = useState<Chord>({ root: 'C', quality: 'major' });
  const [inversion, setInversion] = useState(0);
  const [octave, setOctave] = useState(4);
  const [useAudio, setUseAudio] = useState(false);
  const [audioNotes, setAudioNotes] = useState<Note[] | null>(null);
  const pendingCirclePreview = useRef(false);
  const { timbre, bpm } = useSelector(selectSettings);
  const sounding = useSelector(selectSoundingNotes);
  const detectorNotes = useAudio ? audioNotes ?? [] : sounding;
  const playback = useChordPreview(timbre);
  const { play, stop, isPlaying } = playback;
  const key = circleOfFifths[keyIndex];
  const degrees = diatonicChords(key[mode], mode);
  const notes = chordVoicing(chord, octave, inversion);
  const tones = chordTones(chord);
  const bass = tones[inversion];
  const detected = detectChords(detectorNotes).map(match => ({
    ...match,
    root:
      degrees.find(degree => pitchClass(degree.root) === pitchClass(match.root))
        ?.root ?? match.root,
  }));
  const timbreInfo = timbresLinks.find(item => item.title === timbre);
  const unpitched =
    timbreInfo?.setup === 'drums' || timbreInfo?.setup === 'articulations';
  const firstPitch = Number(notes[0].slice(-1)) * 12;
  const pianoNotes = Array.from(
    { length: 24 },
    (_, offset) =>
      `${chromaticNotes[offset % 12]}${Math.floor(
        (firstPitch + offset) / 12,
      )}` as Note,
  );
  const fixedNotes = fixedNotesFor(timbre);
  useKeyboardInput('chords', {
    source: 'chord-keyboard',
    noteByKey: code => {
      const note = pianoNotes[applicatures.chromatic.indexOf(code)];
      return note && (!fixedNotes || fixedNotes.includes(note)) ? note : null;
    },
  });

  useEffect(() => {
    stop();
    // Дочерние панели сначала освобождают прежний звук при смене аккорда.
    if (pendingCirclePreview.current && !unpitched) {
      play(chordVoicing(chord, octave, inversion));
    }
    pendingCirclePreview.current = false;
  }, [chord, inversion, octave, play, stop, unpitched]);

  const selectChord = (next: Chord, nextInversion = 0, nextOctave?: number) => {
    setChord(next);
    setInversion(nextInversion);
    if (nextOctave !== undefined) setOctave(nextOctave);
  };

  return (
    <PageWrapper aria-label="Chords">
      <Helmet>
        <title>Chords and circle of fifths</title>
      </Helmet>
      <Layout>
        <CirclePanel aria-label="Choose a key">
          <PanelHeader>
            <h2>Circle of fifths</h2>
            <Muted>Clockwise: fifths · counterclockwise: fourths</Muted>
          </PanelHeader>
          <CircleOfFifths
            keyIndex={keyIndex}
            mode={mode}
            chord={chord}
            detected={detected}
            onSelect={(index, nextMode) => {
              pendingCirclePreview.current = true;
              setKeyIndex(index);
              setMode(nextMode);
              selectChord({
                root: circleOfFifths[index][nextMode],
                quality: nextMode,
              });
            }}
          />
          <CircleCaption>
            <span>Outer ring: major · inner ring: minor</span>
            <span>Select a segment to hear the chord.</span>
            <span>{key.signature}</span>
          </CircleCaption>
          <Legend>
            <span>
              <i />
              Selected chord
            </span>
            <span>
              <i />
              Playing chord
            </span>
          </Legend>
        </CirclePanel>
        <Details>
          <LivePanel aria-label="Chord detector">
            <h2>Chord detector</h2>
            <Sources role="group" aria-label="Chord detector input">
              <button
                type="button"
                aria-pressed={!useAudio}
                onClick={() => {
                  setUseAudio(false);
                  setAudioNotes(null);
                }}
              >
                Keys &amp; MIDI
              </button>
              <button
                type="button"
                aria-pressed={useAudio}
                onClick={() => setUseAudio(true)}
              >
                Guitar / mic
              </button>
            </Sources>
            <LiveStatus role="status">
              {detected.length
                ? detected.map(chordSymbol).join(' / ')
                : useAudio && !audioNotes
                ? 'Waiting for audio input'
                : new Set(detectorNotes.map(pitchClass)).size >= 3
                ? 'No exact match'
                : 'Play a chord'}
            </LiveStatus>
            {!!detectorNotes.length && (
              <Muted aria-label="Detected notes">
                {detectorNotes.map(formatPitch).join(' · ')}
              </Muted>
            )}
            {useAudio ? (
              <ChordAudioInput onNotes={setAudioNotes} />
            ) : (
              <Muted>
                Hold several keys on your computer, onscreen piano, or MIDI
                controller.
              </Muted>
            )}
          </LivePanel>
          <Panel aria-label="Selected chord">
            <Muted>SELECTED CHORD</Muted>
            <ChordTitle>
              {chordSymbol(chord)}
              {inversion > 0 && <small>/{formatPitch(bass)}</small>}
            </ChordTitle>
            <Muted>{chordQualities[chord.quality].label}</Muted>
            <ToneList aria-label="Chord tones">
              {tones.map((tone, index) => (
                <Tone key={tone}>
                  <strong>{formatPitch(tone)}</strong>
                  <span>
                    {
                      [
                        'Root',
                        chord.quality === 'sus2'
                          ? 'Second'
                          : chord.quality === 'sus4'
                          ? 'Fourth'
                          : 'Third',
                        'Fifth',
                        'Seventh',
                      ][index]
                    }
                  </span>
                </Tone>
              ))}
            </ToneList>
            <Fields>
              <Field>
                Chord type
                <select
                  value={chord.quality}
                  onChange={event =>
                    selectChord({
                      root: chord.root,
                      quality: event.target.value as ChordQuality,
                    })
                  }
                >
                  {(Object.keys(chordQualities) as ChordQuality[]).map(
                    quality => (
                      <option key={quality} value={quality}>
                        {chordQualities[quality].label}
                      </option>
                    ),
                  )}
                </select>
              </Field>
              <SmallFields>
                <Field>
                  Inversion
                  <select
                    value={inversion}
                    onChange={event => setInversion(Number(event.target.value))}
                  >
                    {tones.map((_, index) => (
                      <option key={index} value={index}>
                        {index === 0 ? 'Root position' : `Inversion ${index}`}
                      </option>
                    ))}
                  </select>
                </Field>
                <Field>
                  Root octave
                  <select
                    value={octave}
                    onChange={event => setOctave(Number(event.target.value))}
                  >
                    {[2, 3, 4, 5].map(value => (
                      <option key={value} value={value}>
                        {value}
                      </option>
                    ))}
                  </select>
                </Field>
              </SmallFields>
            </Fields>
            <ChordPiano aria-label="Chord notes on the piano">
              {pianoNotes.map((note, index) => (
                <PianoKey
                  key={note}
                  note={note}
                  isPressed={sounding.includes(note)}
                  isHighlighted={notes.includes(note)}
                  keyboardLabel={
                    keyboardButtons[applicatures.chromatic[index]].title
                  }
                />
              ))}
            </ChordPiano>
            <Muted>
              Notes from low to high: {notes.map(formatPitch).join(' · ')}
            </Muted>
            <PlayButton
              type="button"
              disabled={unpitched}
              aria-pressed={isPlaying}
              onClick={() => (isPlaying ? stop() : play(notes))}
            >
              {isPlaying ? 'Stop' : 'Preview chord'}
            </PlayButton>
            <Muted>
              {unpitched
                ? 'Choose a pitched instrument in the toolbar to hear the chord.'
                : 'You’ll hear the selected instrument and its effects.'}
            </Muted>
          </Panel>
        </Details>
      </Layout>
      <HarmonyPanel aria-label="Chords in this key">
        <h2>
          Chords in this key {chordSymbol({ root: key[mode], quality: mode })}
        </h2>
        <Muted>
          {mode === 'major'
            ? 'Seven triads of the major scale.'
            : 'Seven triads of natural minor. In harmonic minor, the fifth-degree chord becomes major.'}{' '}
          Click a chord to see its notes.
        </Muted>
        <DegreeList>
          {degrees.map(degree => (
            <DegreeButton
              key={degree.degree}
              type="button"
              aria-label={`${degree.degree}: ${chordSymbol(degree)}`}
              aria-pressed={
                degree.root === chord.root && degree.quality === chord.quality
              }
              onClick={() => selectChord(degree)}
            >
              <span>{degree.degree}</span>
              <strong>{chordSymbol(degree)}</strong>
            </DegreeButton>
          ))}
        </DegreeList>
      </HarmonyPanel>
      <GuitarFingerings
        chord={chord}
        inversion={inversion}
        onPlay={play}
        onStop={stop}
        unpitched={!!unpitched}
      />
      <HarmonyExplorer
        tonic={key[mode]}
        mode={mode}
        chord={chord}
        octave={octave}
        inversion={inversion}
        bpm={bpm}
        unpitched={!!unpitched}
        playback={playback}
        onSelect={selectChord}
      />
    </PageWrapper>
  );
};

const Layout = styled.div`
  display: grid;
  grid-template-columns: minmax(0, 1.2fr) minmax(0, 1fr);
  gap: 24px;
  align-items: start;
  @media (max-width: 900px) {
    grid-template-columns: minmax(0, 1fr);
    gap: 16px;
  }
`;
const Panel = styled.section`
  min-width: 0;
  padding: 24px;
  border: 1px solid ${p => p.theme.border};
  border-radius: 16px;
  background: ${p => p.theme.surface};
  h2 {
    margin: 0 0 8px;
    font-size: 18px;
    font-weight: 600;
  }
  @media (max-width: 520px) {
    padding: 16px;
  }
`;
const CirclePanel = styled(Panel)`
  padding: 24px 14px;
  @media (max-width: 520px) {
    padding: 20px 4px;
  }
`;
const PanelHeader = styled.div`
  padding: 0 10px;
`;
const Muted = styled.div`
  color: ${p => p.theme.textSecondary};
  font-size: 12px;
  line-height: 1.6;
`;
const CircleCaption = styled(Muted)`
  display: grid;
  gap: 4px;
  text-align: center;
  padding: 4px 12px;
`;
const Legend = styled.div`
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 8px 18px;
  margin-top: 16px;
  font-size: 11px;
  color: ${p => p.theme.textSecondary};
  span {
    display: flex;
    align-items: center;
    gap: 6px;
  }
  i {
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background: ${p => p.theme.primary};
  }
  span:last-child i {
    background: ${p => p.theme.pitchDown};
  }
`;
const Details = styled.div`
  display: grid;
  gap: 16px;
  min-width: 0;
`;
const ChordTitle = styled.h2`
  && {
    margin: 8px 0 0;
    font-size: 54px;
    line-height: 1.1;
    font-weight: 600;
    letter-spacing: -2px;
  }
  small {
    font-size: 32px;
    color: ${p => p.theme.textSecondary};
  }
`;
const ToneList = styled.div`
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  margin: 20px 0;
`;
const Tone = styled.div`
  display: grid;
  gap: 4px;
  min-width: 58px;
  padding: 10px 12px;
  background: ${p => p.theme.borderLight};
  border-radius: 8px;
  strong {
    font-size: 20px;
    font-weight: 600;
  }
  span {
    color: ${p => p.theme.textSecondary};
    font-size: 10px;
  }
`;
const Fields = styled.div`
  display: grid;
  gap: 12px;
  margin-bottom: 20px;
`;
const Field = styled.label`
  display: grid;
  gap: 6px;
  min-width: 0;
  font-size: 12px;
  color: ${p => p.theme.textSecondary};
  select {
    width: 100%;
    min-width: 0;
    height: 40px;
    font-size: 13px;
  }
`;
const SmallFields = styled.div`
  display: grid;
  align-items: end;
  grid-template-columns: minmax(0, 1.5fr) minmax(0, 1fr);
  gap: 12px;
`;
const ChordPiano = styled.div`
  display: flex;
  margin-bottom: 10px;
  min-width: 0;
  [data-note] {
    white-space: nowrap;
  }
  .white {
    flex: 1;
    min-width: 0;
  }
  .black {
    flex: 0 0 5%;
    width: 5%;
    margin-right: -5%;
    left: -2.5%;
  }
`;
const PlayButton = styled.button`
  width: 100%;
  min-height: 44px;
  margin: 18px 0 8px;
  padding: 10px 16px;
  border: 1px solid ${p => p.theme.primary};
  border-radius: 8px;
  background: ${p => p.theme.primary};
  color: ${p => p.theme.onPrimary};
  font-weight: 600;
  cursor: pointer;
  &:hover {
    background: ${p => p.theme.primaryHover};
  }
  &:disabled {
    opacity: 0.5;
    cursor: default;
  }
`;
const LivePanel = styled(Panel)`
  border-left: 3px solid ${p => p.theme.pitchDown};
`;
const Sources = styled.div`
  display: flex;
  flex-wrap: wrap;
  gap: 8px;

  button {
    min-height: 40px;
    font-size: 13px;
  }
  button[aria-pressed='true'] {
    border-color: ${p => p.theme.primary};
    background: ${p => p.theme.borderLight};
  }
`;
const LiveStatus = styled.div`
  margin: 8px 0;
  font-size: 22px;
  font-weight: 600;
`;
const HarmonyPanel = styled(Panel)`
  margin: 24px 0 36px;
`;
const DegreeList = styled.div`
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 8px;
  margin-top: 20px;
  @media (max-width: 520px) {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }
`;
const DegreeButton = styled.button`
  display: grid;
  gap: 8px;
  min-height: 76px;
  padding: 12px 4px;
  border: 1px solid ${p => p.theme.border};
  border-radius: 8px;
  background: ${p => p.theme.background};
  color: ${p => p.theme.text};
  cursor: pointer;
  span {
    color: ${p => p.theme.textSecondary};
    font-size: 11px;
  }
  strong {
    font-size: 18px;
    font-weight: 600;
  }
  &:hover,
  &[aria-pressed='true'] {
    border-color: ${p => p.theme.primary};
    background: ${p => p.theme.borderLight};
  }
  &:focus-visible {
    outline: 2px solid ${p => p.theme.primary};
    outline-offset: 2px;
  }
`;
