// One repeat in CSS pixels. A4 has a 12.5 px wavelength, A5 has 6.25 px.
// Combined with frequency / 64 animation, pitches share the same wave speed.
export const getStringWave = (frequency: number) => {
  const wavelength = 5500 / frequency;
  const segments = 32;
  const path = Array.from({ length: segments + 1 }, (_, index) => {
    const position = index / segments;
    const x = 32 + 6 * Math.sin(2 * Math.PI * position);
    const y = wavelength * position;
    return `${index ? 'L' : 'M'}${Number(x.toFixed(3))} ${Number(
      y.toFixed(6),
    )}`;
  }).join(' ');
  return { wavelength, path };
};
