import { useEffect, useState } from 'react';
import styled from 'styled-components';

import { useConnectedGuitarInput } from 'app/services/GuitarInputService/context';
import type { Note } from 'app/services/NotesService/types';

type Props = {
  entering: boolean;
  playing: boolean;
  onEntering: (entering: boolean) => void;
  onNote: (note: Note) => void;
};

export const GuitarEntry = ({
  entering,
  playing,
  onEntering,
  onNote,
}: Props) => {
  const guitar = useConnectedGuitarInput();
  const { connected, subscribeNotes } = guitar;
  const [error, setError] = useState('');

  useEffect(() => {
    if (!entering) return;
    if (!connected) {
      onEntering(false);
      return;
    }
    let active = true;
    let lastAttack = -1;
    const unsubscribe = subscribeNotes(
      ({ events }) => {
        if (!active) return;
        for (const event of events) {
          if (event.id <= lastAttack) continue;
          lastAttack = event.id;
          onNote(event.note.note);
        }
      },
      () => {
        if (!active) return;
        active = false;
        setError('Note recognition stopped. Start note entry again to retry.');
        onEntering(false);
      },
      true,
    );
    return () => {
      active = false;
      unsubscribe();
    };
  }, [connected, entering, onEntering, onNote, subscribeNotes]);

  const locked = entering || guitar.connecting || guitar.isRecording;
  return (
    <Panel aria-label="Guitar note entry">
      <Controls>
        <label>
          Audio input
          <select
            value={guitar.deviceId}
            disabled={locked || !guitar.supported}
            onChange={event => void guitar.connect(event.target.value, false)}
          >
            <option value="">System microphone / audio interface</option>
            {guitar.deviceId &&
              !guitar.devices.some(
                device => device.deviceId === guitar.deviceId,
              ) && (
                <option value={guitar.deviceId}>Selected audio input</option>
              )}
            {guitar.devices.map(device => (
              <option key={device.deviceId} value={device.deviceId}>
                {device.label || 'Audio input'}
              </option>
            ))}
          </select>
        </label>
        {connected && guitar.channels > 1 && (
          <label>
            Input channel
            <select
              value={guitar.channel}
              disabled={locked}
              onChange={event =>
                guitar.selectChannel(Number(event.target.value))
              }
            >
              {Array.from({ length: guitar.channels }, (_, channel) => (
                <option key={channel} value={channel}>
                  {channel + 1}
                </option>
              ))}
            </select>
          </label>
        )}
        <button
          type="button"
          disabled={guitar.isRecording || !guitar.supported}
          onClick={() => {
            if (connected || guitar.connecting) {
              onEntering(false);
              void guitar.disconnect();
            } else void guitar.connect(guitar.deviceId, false);
          }}
        >
          {guitar.connecting
            ? 'Cancel connection'
            : connected
            ? 'Disconnect guitar'
            : 'Connect guitar'}
        </button>
        <button
          type="button"
          className={entering ? 'selected' : undefined}
          disabled={
            playing || !connected || guitar.connecting || guitar.isRecording
          }
          onClick={() => {
            setError('');
            onEntering(!entering);
          }}
        >
          {entering ? 'Stop note entry' : 'Start note entry'}
        </button>
        {guitar.monitoring && (
          <button type="button" onClick={guitar.stopMonitoring}>
            Turn off live sound
          </button>
        )}
        {connected && (
          <meter
            min={0}
            max={1}
            value={guitar.level.peak}
            aria-label="Guitar signal"
          />
        )}
      </Controls>
      {!guitar.supported && (
        <p role="alert">Audio input is unavailable in this browser.</p>
      )}
      {guitar.connectionStatus && (
        <p role="status">{guitar.connectionStatus}</p>
      )}
      {entering && <p role="status">Listening for guitar notes…</p>}
      {(guitar.error || error) && <p role="alert">{guitar.error || error}</p>}
    </Panel>
  );
};

const Panel = styled.section`
  padding: 8px 12px;
  border: 1px solid ${p => p.theme.border};
  border-radius: 12px;
  background: ${p => p.theme.surface};

  p {
    margin: 0;
    color: ${p => p.theme.textSecondary};
    font-size: 13px;
  }

  p[role] {
    margin-top: 4px;
  }

  p[role='alert'] {
    color: ${p => p.theme.danger};
  }
`;

const Controls = styled.div`
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 6px;

  label {
    display: grid;
    gap: 4px;
    min-width: 0;
    max-width: 100%;
    color: ${p => p.theme.textSecondary};
    font-size: 13px;
  }

  select {
    max-width: 100%;
  }

  @media (min-width: 701px) {
    label {
      display: flex;
      align-items: center;
      gap: 6px;
    }
  }

  meter {
    align-self: center;
    width: 70px;
  }
`;
