import {
  PointerEvent,
  useEffect,
  useId,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
} from 'react';
import { useSelector } from 'react-redux';
import styled, { css } from 'styled-components';

import {
  getMelodyDuration,
  selectMelodies,
} from 'app/services/MelodiesService';
import {
  MAX_NOTE_PITCH,
  NoteEditMode,
  editNote,
  getEditingStep,
  noteAtPitch,
  notePitch,
} from 'app/services/MelodiesService/editing';
import {
  getBeatsPerMeasure,
  getTimeSignature,
} from 'app/services/MelodiesService/meter';
import {
  Subdivision,
  getNormalizationOptions,
  normalizeMelody,
} from 'app/services/MelodiesService/normalization';
import {
  changeTempo,
  clampTempo,
  estimateTempo,
} from 'app/services/MelodiesService/tempo';
import { getNoteDuration } from 'app/services/MelodiesService/timing';
import { Melody, NoteInMelody } from 'app/services/MelodiesService/types';

import { MelodyActionButton, MelodyActionIcon } from './MelodyAction';
import { MelodyEditorIcon, MelodyEditorPopover } from './MelodyEditorAction';
import { RecordingNormalization } from './RecordingNormalization';

const DEFAULT_ROW_HEIGHT = 28;
const DEFAULT_BEAT_WIDTH = 96;
const LABEL_WIDTH = 52;
const allNotes = Array.from({ length: MAX_NOTE_PITCH + 1 }, (_, i) =>
  noteAtPitch(i),
);

interface Props {
  compact?: boolean;
  melody: Melody;
  onChange: (notes: NoteInMelody[], bpm: number) => void;
  onStop: () => void;
  onPlay?: (melody: Melody, noteIndex?: number) => void;
  isPlaying?: boolean;
  isPaused?: boolean;
  isAudition?: boolean;
  onPause?: () => void;
  onResume?: () => void;
  onSeek?: (position: number) => void;
  position?: number;
  timelinePlaying?: boolean;
}
type Snapshot = { notes: NoteInMelody[]; bpm: number };
const formatPosition = (ms: number) =>
  `${Math.floor(ms / 60000)}:${((Math.floor(ms / 100) % 600) / 10)
    .toFixed(1)
    .padStart(4, '0')}`;

interface Gesture {
  index: number;
  pointerId: number;
  mode: NoteEditMode;
  original: NoteInMelody;
  x: number;
  y: number;
  scrollLeft: number;
  scrollTop: number;
  pixelsPerMs: number;
  rowHeight: number;
  step: number;
}

export const RecordingEditor = ({
  compact = false,
  melody,
  onChange,
  onStop,
  onPlay,
  isPlaying = false,
  isPaused = false,
  isAudition = false,
  onPause,
  onResume,
  onSeek,
  position = 0,
}: Props) => {
  const [snapEnabled, setSnapEnabled] = useState(true);
  const [subdivision, setSubdivision] = useState<Subdivision>(4);
  const [zoom, setZoom] = useState(DEFAULT_BEAT_WIDTH);
  const [rowHeight, setRowHeight] = useState(DEFAULT_ROW_HEIGHT);
  const [selected, setSelected] = useState<number | null>(null);
  const [preview, setPreview] = useState<NoteInMelody | null>(null);
  const [past, setPast] = useState<Snapshot[]>([]);
  const [future, setFuture] = useState<Snapshot[]>([]);
  const skipClick = useRef(false);
  const gesture = useRef<Gesture | null>(null);
  const previewRef = useRef<NoteInMelody | null>(null);
  const lastNotes = useRef(melody.notes);
  const viewport = useRef<HTMLDivElement>(null);
  const timeline = useRef<HTMLDivElement>(null);
  const zoomAnchor = useRef<{
    x: number;
    y: number;
    time: number;
    row: number;
    horizontal: boolean;
    vertical: boolean;
  } | null>(null);
  const skipZoomScroll = useRef(false);
  const seeking = useRef<{ pointerId: number; original: number } | null>(null);
  const [pitchRange, setPitchRange] = useState(() => {
    const pitches = melody.notes.length
      ? melody.notes.map(event => notePitch(event.note))
      : [48];
    const low = Math.max(0, Math.min(...pitches) - 4);
    return {
      low,
      high: Math.min(
        MAX_NOTE_PITCH,
        Math.max(Math.max(...pitches) + 4, low + 11),
      ),
    };
  });
  const previousHigh = useRef(pitchRange.high);
  const initialScroll = useRef(false);
  useLayoutEffect(() => {
    const element = viewport.current;
    if (!compact || initialScroll.current || !element?.clientHeight) return;
    const firstPitch = notePitch(melody.notes[0]?.note ?? 'C4');
    element.scrollTop = Math.max(
      0,
      26 +
        (pitchRange.high - firstPitch) * rowHeight -
        element.clientHeight / 2,
    );
    initialScroll.current = true;
  }, [compact, melody.notes, pitchRange.high, rowHeight]);
  const [viewportWidth, setViewportWidth] = useState(0);
  const hintId = useId();
  const { soundingNoteIndices } = useSelector(selectMelodies);
  const estimate = useMemo(() => estimateTempo(melody.notes), [melody.notes]);
  const bpm =
    melody.bpm && Number.isFinite(melody.bpm) && melody.bpm > 0
      ? melody.bpm
      : estimate?.bpm ?? getNormalizationOptions(melody).bpm;
  const current = { notes: melody.notes, bpm };
  const beatMs = 60000 / bpm;
  const step = getEditingStep(
    { ...melody, bpm },
    snapEnabled ? subdivision : 0,
  );
  const pixelsPerMs = zoom / beatMs;
  const beatsPerMeasure = getBeatsPerMeasure(melody.timeSignature);
  const [countsPerMeasure, unit] = getTimeSignature(melody.timeSignature)
    .split('/')
    .map(Number);
  const quartersPerCount = 4 / unit;
  const beats = Math.max(
    beatsPerMeasure,
    Math.ceil((viewportWidth - LABEL_WIDTH) / zoom),
    Math.ceil(getMelodyDuration(melody) / beatMs) + 2,
  );
  const { low: lowest, high: highest } = pitchRange;
  useLayoutEffect(() => {
    const pitches = melody.notes.map(event => notePitch(event.note));
    const low = Math.max(
      0,
      Math.min(lowest, ...pitches.map(pitch => pitch - 4)),
    );
    const high = Math.min(
      MAX_NOTE_PITCH,
      Math.max(highest, ...pitches.map(pitch => pitch + 4)),
    );
    if (low !== lowest || high !== highest) setPitchRange({ low, high });
    if (viewport.current && highest > previousHigh.current)
      viewport.current.scrollTop +=
        (highest - previousHigh.current) * rowHeight;
    previousHigh.current = highest;
  }, [melody.notes, lowest, highest, rowHeight]);
  const rows = Array.from(
    { length: highest - lowest + 1 },
    (_, i) => highest - i,
  );
  const selectedNote = selected === null ? undefined : melody.notes[selected];

  useLayoutEffect(() => {
    const anchor = zoomAnchor.current;
    const element = viewport.current;
    if (!anchor || !element) return;
    if (anchor.horizontal)
      element.scrollLeft = Math.max(
        0,
        LABEL_WIDTH + anchor.time * pixelsPerMs - anchor.x,
      );
    if (anchor.vertical)
      element.scrollTop = Math.max(0, 26 + anchor.row * rowHeight - anchor.y);
    zoomAnchor.current = null;
  }, [zoom, rowHeight, pixelsPerMs]);

  useEffect(() => {
    if (skipZoomScroll.current) {
      skipZoomScroll.current = false;
      return;
    }
    const element = viewport.current;
    if (!element || gesture.current || seeking.current) return;
    const x = LABEL_WIDTH + position * pixelsPerMs;
    if (
      x > element.scrollLeft + element.clientWidth - 30 ||
      x < element.scrollLeft + LABEL_WIDTH
    )
      element.scrollLeft = Math.max(0, x - element.clientWidth / 3);
  }, [position, pixelsPerMs]);

  useEffect(() => {
    const element = viewport.current;
    if (!element) return;
    const measure = () => setViewportWidth(element.clientWidth);
    const resetGesture = () => {
      seeking.current = null;
      gesture.current = null;
      previewRef.current = null;
      setPreview(null);
    };
    measure();
    const observer =
      typeof ResizeObserver === 'undefined'
        ? undefined
        : new ResizeObserver(measure);
    observer?.observe(element);
    window.addEventListener('resize', measure);
    window.addEventListener('blur', resetGesture);
    return () => {
      observer?.disconnect();
      window.removeEventListener('resize', measure);
      window.removeEventListener('blur', resetGesture);
    };
  }, []);

  useEffect(() => {
    // Normalization or restoring the original starts a new editor history.
    if (melody.notes !== lastNotes.current) {
      setPast([]);
      setFuture([]);
      setSelected(null);
      seeking.current = null;
      gesture.current = null;
      previewRef.current = null;
      setPreview(null);
    }
    lastNotes.current = melody.notes;
  }, [melody.notes]);

  const apply = (snapshot: Snapshot) => {
    lastNotes.current = snapshot.notes;
    onChange(snapshot.notes, snapshot.bpm);
  };
  const commitSnapshot = (snapshot: Snapshot) => {
    setPast(history => [...history.slice(-99), current]);
    setFuture([]);
    apply(snapshot);
  };
  const commit = (index: number, note: NoteInMelody) => {
    const original = melody.notes[index];
    if (
      original.note === note.note &&
      original.start === note.start &&
      original.duration === note.duration
    )
      return;
    commitSnapshot({
      bpm,
      notes: melody.notes.map((event, i) => (i === index ? note : event)),
    });
  };
  const cancel = () => {
    if (previewRef.current) skipClick.current = true;
    gesture.current = null;
    previewRef.current = null;
    setPreview(null);
  };
  const changeZoom = (nextZoom: number, nextRowHeight: number) => {
    if (nextZoom === zoom && nextRowHeight === rowHeight) return;
    cancel();
    seeking.current = null;
    const element = viewport.current;
    if (element) {
      const cursorX = LABEL_WIDTH + position * pixelsPerMs - element.scrollLeft;
      const x =
        cursorX >= LABEL_WIDTH && cursorX <= element.clientWidth - 20
          ? cursorX
          : LABEL_WIDTH + Math.max(0, element.clientWidth - LABEL_WIDTH) / 2;
      const selectedY = selectedNote
        ? 26 +
          (highest - notePitch(selectedNote.note) + 0.5) * rowHeight -
          element.scrollTop
        : -1;
      const y =
        selectedY >= 26 && selectedY <= element.clientHeight
          ? selectedY
          : 26 + Math.max(0, element.clientHeight - 26) / 2;
      zoomAnchor.current = {
        x,
        y,
        time: (element.scrollLeft + x - LABEL_WIDTH) / pixelsPerMs,
        row: (element.scrollTop + y - 26) / rowHeight,
        horizontal: nextZoom !== zoom,
        vertical: nextRowHeight !== rowHeight,
      };
    }
    skipZoomScroll.current = nextZoom !== zoom;
    setZoom(nextZoom);
    setRowHeight(nextRowHeight);
  };
  const addNote = (
    time = position,
    pitch = notePitch(selectedNote?.note ?? melody.notes[0]?.note ?? 'C4'),
  ) => {
    const start = Math.max(
      0,
      Math.round(step ? Math.round(time / step) * step : time),
    );
    const duration = getNoteDuration(
      selectedNote ?? { note: 'C4', start: 0, duration: beatMs },
    );
    const note = {
      note: noteAtPitch(pitch),
      start,
      duration: Math.max(
        1,
        Math.round(step ? Math.round(duration / step) * step : duration),
      ),
    };
    commitSnapshot({ bpm, notes: [...melody.notes, note] });
    setSelected(melody.notes.length);
  };
  const removeNote = () => {
    if (selected === null || !selectedNote) return;
    cancel();
    commitSnapshot({
      bpm,
      notes: melody.notes.filter((_, index) => index !== selected),
    });
    setSelected(null);
    viewport.current?.focus();
  };
  const timeAt = (x: number) =>
    Math.max(
      0,
      (x -
        (timeline.current?.getBoundingClientRect().left ?? 0) -
        LABEL_WIDTH) /
        pixelsPerMs,
    );
  const beginSeek = (event: PointerEvent<HTMLElement>) => {
    if (event.button !== 0 || !onSeek || !melody.notes.length) return;
    event.preventDefault();
    event.stopPropagation();
    event.currentTarget.focus();
    event.currentTarget.setPointerCapture?.(event.pointerId);
    seeking.current = { pointerId: event.pointerId, original: position };
    onSeek(timeAt(event.clientX));
  };
  const begin = (
    event: PointerEvent<HTMLElement>,
    index: number,
    mode: NoteEditMode,
  ) => {
    if (event.button !== 0 || gesture.current) return;
    event.preventDefault();
    event.stopPropagation();
    skipClick.current = false;
    setSelected(index);
    event.currentTarget.focus();
    event.currentTarget.setPointerCapture?.(event.pointerId);
    gesture.current = {
      index,
      mode,
      pointerId: event.pointerId,
      original: melody.notes[index],
      x: event.clientX,
      y: event.clientY,
      scrollLeft: viewport.current?.scrollLeft ?? 0,
      scrollTop: viewport.current?.scrollTop ?? 0,
      pixelsPerMs,
      rowHeight,
      step,
    };
  };
  const move = (event: PointerEvent) => {
    const drag = gesture.current;
    if (!drag || drag.pointerId !== event.pointerId) return;
    const dx =
      event.clientX -
      drag.x +
      (viewport.current?.scrollLeft ?? 0) -
      drag.scrollLeft;
    const dy =
      event.clientY -
      drag.y +
      (viewport.current?.scrollTop ?? 0) -
      drag.scrollTop;
    if (!previewRef.current && Math.abs(dx) < 3 && Math.abs(dy) < 3) return;
    const note = editNote(
      drag.original,
      drag.mode,
      dx / drag.pixelsPerMs,
      Math.round(-dy / drag.rowHeight),
      drag.step,
    );
    previewRef.current = note;
    setPreview(note);
  };
  const end = (event: PointerEvent) => {
    const drag = gesture.current;
    if (!drag || drag.pointerId !== event.pointerId) return;
    move(event);
    if (previewRef.current) commit(drag.index, previewRef.current);
    cancel();
  };
  const audition = (index: number) => {
    setSelected(index);
    onPlay?.(
      { ...melody, bpm, notes: [{ ...melody.notes[index], start: 0 }] },
      index,
    );
  };

  const Button = compact ? MelodyActionButton : 'button';
  const tempoDetails = (
    <Hint>
      {estimate ? (
        <>
          Estimated tempo: {estimate.bpm} BPM
          {estimate.confidence === 'low' ? ' (approximate)' : ''}.{' '}
          <button
            type="button"
            onClick={() =>
              commitSnapshot({ notes: melody.notes, bpm: estimate.bpm })
            }
          >
            Accept estimate
          </button>
          {estimate.alternatives.length > 0 && (
            <>
              {' '}
              Other options:{' '}
              {estimate.alternatives.map(value => (
                <button
                  type="button"
                  key={value}
                  onClick={() =>
                    commitSnapshot({ notes: melody.notes, bpm: value })
                  }
                >
                  {value} BPM
                </button>
              ))}
            </>
          )}
        </>
      ) : (
        'Not enough rhythmic events for a reliable tempo estimate.'
      )}{' '}
      Change BPM to speed up or slow down the melody. Use the estimate to move
      the grid without changing playback speed.
    </Hint>
  );
  const zoomControls = (
    <Toolbar aria-label="Timeline zoom">
      <ZoomControl>
        Time zoom
        <input
          type="range"
          min={25}
          max={400}
          step={25}
          value={Math.round((zoom / DEFAULT_BEAT_WIDTH) * 100)}
          onChange={event =>
            changeZoom(
              (DEFAULT_BEAT_WIDTH * +event.target.value) / 100,
              rowHeight,
            )
          }
        />
        <output aria-hidden="true">
          {Math.round((zoom / DEFAULT_BEAT_WIDTH) * 100)}%
        </output>
      </ZoomControl>
      <ZoomControl>
        Pitch zoom
        <input
          type="range"
          min={50}
          max={200}
          step={25}
          value={Math.round((rowHeight / DEFAULT_ROW_HEIGHT) * 100)}
          onChange={event =>
            changeZoom(zoom, (DEFAULT_ROW_HEIGHT * +event.target.value) / 100)
          }
        />
        <output aria-hidden="true">
          {Math.round((rowHeight / DEFAULT_ROW_HEIGHT) * 100)}%
        </output>
      </ZoomControl>
      <button
        type="button"
        disabled={
          zoom === DEFAULT_BEAT_WIDTH && rowHeight === DEFAULT_ROW_HEIGHT
        }
        onClick={() => changeZoom(DEFAULT_BEAT_WIDTH, DEFAULT_ROW_HEIGHT)}
      >
        Reset zoom
      </button>
    </Toolbar>
  );
  const help = (
    <Hint id={hintId}>
      Drag a note or use the arrow keys to move it. Resize it at either edge or
      use Shift + ←/→. Click a note or press Enter to hear it. Escape cancels
      the edit. Double-click empty space to add a note. Delete or Backspace
      removes the selected note. To jump to a point in the take, click the ruler
      or drag the playhead.
    </Hint>
  );
  const selectionControls =
    selectedNote && selected !== null ? (
      <Toolbar
        key={`${selected}:${selectedNote.start}:${selectedNote.duration}:${selectedNote.note}`}
        aria-label="Selected note"
      >
        <strong>Note {selected + 1}</strong>
        <label>
          Pitch
          <select
            value={selectedNote.note}
            onChange={event =>
              commit(selected, {
                ...selectedNote,
                note: event.target.value as NoteInMelody['note'],
              })
            }
          >
            {allNotes.map(note => (
              <option key={note}>{note}</option>
            ))}
          </select>
        </label>
        <label>
          Start, ms
          <input
            type="number"
            min={0}
            step={1}
            defaultValue={selectedNote.start}
            onKeyDown={event => {
              if (event.key === 'Enter') event.currentTarget.blur();
            }}
            onBlur={event => {
              const value = event.currentTarget.valueAsNumber;
              if (Number.isFinite(value))
                commit(selected, {
                  ...selectedNote,
                  start: Math.max(0, Math.round(value)),
                });
            }}
          />
        </label>
        <label>
          Duration, ms
          <input
            type="number"
            min={1}
            step={1}
            defaultValue={getNoteDuration(selectedNote)}
            onKeyDown={event => {
              if (event.key === 'Enter') event.currentTarget.blur();
            }}
            onBlur={event => {
              const value = event.currentTarget.valueAsNumber;
              if (Number.isFinite(value))
                commit(selected, {
                  ...selectedNote,
                  duration: Math.max(1, Math.round(value)),
                });
            }}
          />
        </label>
        <span>Exact values without snapping</span>
      </Toolbar>
    ) : null;
  const playLabel =
    isPlaying && !isAudition ? 'Pause' : isPaused ? 'Resume' : 'Play melody';

  return (
    <Editor
      $compact={compact}
      aria-label="Melody editor"
      onKeyDown={event => {
        event.stopPropagation();
        if (event.key === 'Escape') {
          if (seeking.current) onSeek?.(seeking.current.original);
          seeking.current = null;
          cancel();
        }
        const target = event.target as HTMLElement;
        if (target.closest('input, select, textarea, [contenteditable="true"]'))
          return;
        if (event.key === 'Delete' || event.key === 'Backspace') {
          event.preventDefault();
          removeNote();
        } else if (event.key === 'Insert') {
          event.preventDefault();
          addNote();
        }
      }}
    >
      <Transport aria-label="Editor playback">
        <Button
          type="button"
          aria-label={playLabel}
          title={playLabel}
          disabled={!onPlay || !melody.notes.length}
          onClick={() => {
            if (isPlaying && !isAudition) (onPause ?? onStop)();
            else if (isPaused && onResume) onResume();
            else onPlay?.({ ...melody, bpm });
          }}
        >
          {compact ? (
            isPlaying && !isAudition ? (
              <MelodyEditorIcon icon="pause" />
            ) : (
              <MelodyActionIcon action="play" />
            )
          ) : (
            playLabel
          )}
        </Button>
        <Button
          type="button"
          disabled={!isPlaying && !isPaused && position === 0}
          aria-label="Stop"
          title="Stop"
          onClick={onStop}
        >
          {compact ? <MelodyActionIcon action="stop" /> : 'Stop'}
        </Button>
        <output role="timer" aria-label="Playback position">
          {formatPosition(position)} /{' '}
          {formatPosition(getMelodyDuration(melody))}
        </output>
        <label>
          {compact ? 'BPM' : 'Tempo, BPM'}
          <input
            aria-label="Tempo, BPM"
            key={bpm}
            type="number"
            min={40}
            max={220}
            step={1}
            defaultValue={bpm}
            onKeyDown={event => {
              if (event.key === 'Enter') event.currentTarget.blur();
            }}
            onBlur={event => {
              const value = event.currentTarget.valueAsNumber;
              if (!Number.isFinite(value)) {
                event.currentTarget.value = String(bpm);
                return;
              }
              const next = clampTempo(value);
              event.currentTarget.value = String(next);
              if (next !== bpm)
                commitSnapshot({
                  bpm: next,
                  notes: changeTempo(melody.notes, bpm, next),
                });
            }}
          />
        </label>
        <RecordingNormalization
          compact={compact}
          key={bpm}
          melody={{ ...melody, bpm }}
          durationsOnly
          canRestore={false}
          isPlaying={isPlaying}
          onStop={onStop}
          onPreview={piece => onPlay?.(piece)}
          onRestore={() => {}}
          onApply={options => {
            const result = normalizeMelody({ ...melody, bpm }, options).melody;
            commitSnapshot({ notes: result.notes, bpm: result.bpm! });
          }}
        />
        {compact && (
          <MelodyEditorPopover label="Tempo estimate" icon="tempo">
            {tempoDetails}
          </MelodyEditorPopover>
        )}
        {!compact && (
          <SeekControl>
            Timeline position
            <input
              type="range"
              min={0}
              max={Math.max(1, Math.ceil(getMelodyDuration(melody)))}
              step={1}
              value={Math.round(position)}
              disabled={!onSeek || !melody.notes.length}
              onChange={event => onSeek?.(+event.target.value)}
            />
          </SeekControl>
        )}
      </Transport>
      {!compact && tempoDetails}
      <Toolbar>
        {!compact && <strong>Melody editor</strong>}
        <Button
          type="button"
          aria-label="Add note"
          title="Add note"
          onClick={() => addNote()}
        >
          {compact ? <MelodyEditorIcon icon="add" /> : 'Add note'}
        </Button>
        <Button
          type="button"
          aria-label="Delete note"
          title="Delete note"
          disabled={!selectedNote}
          onClick={removeNote}
        >
          {compact ? <MelodyEditorIcon icon="delete" /> : 'Delete note'}
        </Button>
        {compact ? (
          <MelodyActionButton
            type="button"
            role="checkbox"
            aria-label="Snap to grid"
            title="Snap to grid"
            aria-checked={snapEnabled}
            onClick={() => setSnapEnabled(!snapEnabled)}
          >
            <MelodyEditorIcon icon="snap" />
          </MelodyActionButton>
        ) : (
          <label>
            <input
              type="checkbox"
              checked={snapEnabled}
              onChange={event => setSnapEnabled(event.target.checked)}
            />
            Snap to grid
          </label>
        )}
        <label>
          {!compact && 'Grid'}
          <select
            aria-label="Grid"
            value={subdivision}
            disabled={!snapEnabled}
            onChange={event =>
              setSubdivision(+event.target.value as Subdivision)
            }
          >
            <option value={1}>1/4</option>
            <option value={2}>1/8</option>
            <option value={4}>1/16</option>
            <option value={8}>1/32</option>
            <option value={3}>1/8 triplets</option>
          </select>
        </label>
        <span>
          {compact
            ? melody.timeSignature ?? '4/4'
            : `${bpm} BPM · ${melody.timeSignature ?? '4/4'}`}
        </span>
        <Button
          type="button"
          aria-label="Undo"
          title="Undo"
          disabled={!past.length}
          onClick={() => {
            setSelected(null);
            setPast(past.slice(0, -1));
            setFuture([current, ...future]);
            apply(past[past.length - 1]);
          }}
        >
          {compact ? <MelodyEditorIcon icon="undo" /> : 'Undo'}
        </Button>
        <Button
          type="button"
          aria-label="Redo"
          title="Redo"
          disabled={!future.length}
          onClick={() => {
            setSelected(null);
            setPast([...past, current]);
            setFuture(future.slice(1));
            apply(future[0]);
          }}
        >
          {compact ? <MelodyEditorIcon icon="redo" /> : 'Redo'}
        </Button>
        {compact && (
          <>
            <MelodyEditorPopover
              label="Note parameters"
              icon="edit"
              disabled={!selectedNote}
            >
              {selectionControls}
            </MelodyEditorPopover>
            <MelodyEditorPopover label="Timeline zoom" icon="zoom">
              {zoomControls}
            </MelodyEditorPopover>
            <MelodyEditorPopover label="Editor help" icon="help">
              {help}
            </MelodyEditorPopover>
          </>
        )}
      </Toolbar>
      {!compact && zoomControls}
      {!compact && help}
      {!melody.notes.length && (
        <Hint>
          No notes yet. Use the button or double-click the grid to add your
          first note.
        </Hint>
      )}
      <Viewport ref={viewport} tabIndex={0} aria-label="Note time grid">
        <Timeline
          ref={timeline}
          onDoubleClick={event => {
            if (
              (event.target as HTMLElement).closest(
                '[data-note-index], [data-ruler], [data-playhead]',
              )
            )
              return;
            const rect = event.currentTarget.getBoundingClientRect();
            const row = Math.floor((event.clientY - rect.top - 26) / rowHeight);
            if (
              event.clientX - rect.left < LABEL_WIDTH ||
              row < 0 ||
              row >= rows.length
            )
              return;
            addNote(timeAt(event.clientX), highest - row);
          }}
          style={{
            width: LABEL_WIDTH + beats * zoom,
            height: 26 + rows.length * rowHeight,
          }}
          onPointerMove={event => {
            if (seeking.current?.pointerId === event.pointerId)
              onSeek?.(timeAt(event.clientX));
            else move(event);
          }}
          onPointerUp={event => {
            if (seeking.current?.pointerId === event.pointerId) {
              onSeek?.(timeAt(event.clientX));
              seeking.current = null;
            } else end(event);
          }}
          onPointerCancel={event => {
            if (seeking.current?.pointerId === event.pointerId)
              seeking.current = null;
            if (gesture.current?.pointerId === event.pointerId) cancel();
          }}
          onLostPointerCapture={event => {
            if (seeking.current?.pointerId === event.pointerId)
              seeking.current = null;
            if (gesture.current?.pointerId === event.pointerId) cancel();
          }}
        >
          <Ruler
            data-ruler
            onPointerDown={beginSeek}
            style={{ width: beats * zoom, marginLeft: LABEL_WIDTH }}
          >
            {Array.from(
              { length: Math.ceil(beats / quartersPerCount) },
              (_, count) => (
                <span
                  key={count}
                  style={{ left: count * quartersPerCount * zoom }}
                >
                  {Math.floor(count / countsPerMeasure) + 1}.
                  {(count % countsPerMeasure) + 1}
                </span>
              ),
            )}
          </Ruler>
          <Grid
            $rowHeight={rowHeight}
            style={{
              left: LABEL_WIDTH,
              width: beats * zoom,
              height: rows.length * rowHeight,
              backgroundSize: `${zoom / subdivision}px ${rowHeight}px, ${
                zoom * quartersPerCount
              }px 100%, ${zoom * beatsPerMeasure}px 100%`,
            }}
          />
          <PitchLabels style={{ height: rows.length * rowHeight }}>
            {rows.map((pitch, row) => (
              <PitchLabel
                key={pitch}
                $black={noteAtPitch(pitch).includes('#')}
                $rowHeight={rowHeight}
                style={{ top: row * rowHeight }}
              >
                {noteAtPitch(pitch)}
              </PitchLabel>
            ))}
          </PitchLabels>
          <Playhead
            data-playhead
            aria-label="Playhead"
            data-position={Math.round(position)}
            style={{
              left: LABEL_WIDTH + position * pixelsPerMs,
              height: 26 + rows.length * rowHeight,
            }}
          >
            <PlayheadGrip
              role="slider"
              tabIndex={0}
              aria-label="Playhead position"
              aria-valuemin={0}
              aria-valuemax={getMelodyDuration(melody)}
              aria-valuenow={Math.round(position)}
              aria-valuetext={formatPosition(position)}
              aria-disabled={!onSeek || !melody.notes.length}
              onPointerDown={beginSeek}
              onKeyDown={event => {
                const next =
                  event.key === 'Home'
                    ? 0
                    : event.key === 'End'
                    ? getMelodyDuration(melody)
                    : event.key === 'ArrowLeft'
                    ? Math.max(0, position - beatMs)
                    : event.key === 'ArrowRight'
                    ? Math.min(getMelodyDuration(melody), position + beatMs)
                    : undefined;
                if (next !== undefined) {
                  event.preventDefault();
                  onSeek?.(next);
                }
              }}
            />
          </Playhead>
          {melody.notes.map((original, index) => {
            const note =
              gesture.current?.index === index && preview ? preview : original;
            const duration = getNoteDuration(note);
            const label = `Note ${index + 1}: ${note.note}`;
            return (
              <NoteBlock
                key={index}
                data-note-index={index}
                role="button"
                tabIndex={0}
                aria-label={label}
                aria-pressed={selected === index}
                aria-describedby={compact ? undefined : hintId}
                title={`${note.note}: start ${note.start} ms, duration ${duration} ms`}
                $rowHeight={rowHeight}
                $selected={selected === index}
                $sounding={soundingNoteIndices.includes(index)}
                style={{
                  left: LABEL_WIDTH + note.start * pixelsPerMs,
                  top: 27 + (highest - notePitch(note.note)) * rowHeight,
                  width: Math.max(4, duration * pixelsPerMs),
                }}
                onFocus={() => setSelected(index)}
                onClick={() => {
                  if (skipClick.current) {
                    skipClick.current = false;
                    return;
                  }
                  audition(index);
                }}
                onPointerDown={event => begin(event, index, 'move')}
                onKeyDown={event => {
                  if (event.key === 'Enter' || event.key === ' ') {
                    event.preventDefault();
                    audition(index);
                    return;
                  }
                  const arrows = [
                    'ArrowLeft',
                    'ArrowRight',
                    'ArrowUp',
                    'ArrowDown',
                  ];
                  if (!arrows.includes(event.key)) return;
                  event.preventDefault();
                  const horizontal =
                    event.key === 'ArrowLeft' || event.key === 'ArrowRight';
                  const direction =
                    event.key === 'ArrowLeft' || event.key === 'ArrowDown'
                      ? -1
                      : 1;
                  commit(
                    index,
                    editNote(
                      original,
                      event.shiftKey && horizontal ? 'resize-end' : 'move',
                      horizontal ? direction * (step || 10) : 0,
                      horizontal ? 0 : direction,
                      step,
                    ),
                  );
                }}
              >
                <Handle
                  aria-hidden="true"
                  $end={false}
                  onPointerDown={event => begin(event, index, 'resize-start')}
                />
                <span>{note.note}</span>
                <Handle
                  aria-hidden="true"
                  $end
                  onPointerDown={event => begin(event, index, 'resize-end')}
                />
              </NoteBlock>
            );
          })}
        </Timeline>
      </Viewport>
      {!compact &&
        (selectionControls ?? (
          <Hint>Select a note to set its exact pitch, start and duration.</Hint>
        ))}
    </Editor>
  );
};

