import { ReactNode, useEffect, useMemo, useState } from 'react';
import { batch, useDispatch, useSelector } from 'react-redux';
import {
  Link,
  useNavigate,
  useParams,
  useSearchParams,
} from 'react-router-dom';
import styled from 'styled-components';

import { keyboardButtons } from 'app/services/KeyboardService';
import {
  selectLibraryMelodies,
  stopMelody,
} from 'app/services/MelodiesService';
import { clampTempo } from 'app/services/MelodiesService/tempo';
import { Melody } from 'app/services/MelodiesService/types';
import {
  getMelodyBpm,
  useActivateMelody,
} from 'app/services/MelodiesService/useCurrentMelody';
import { useRememberMelodyOpened } from 'app/services/MelodiesService/useRememberMelodyOpened';
import { notesActions, selectNotes } from 'app/services/NotesService';
import { getRecordingContext } from 'app/services/NotesService/project';
import {
  HIT_WINDOW,
  LEAD_IN,
  PracticeMode,
  TIMING_TOLERANCES,
  getNoteBindings,
  getSessionStats,
  isRecallMode,
} from 'app/services/PlayAlongService/game';
import { getKeyboardLayout } from 'app/services/PlayAlongService/keyboardLayout';
import { usePlayAlong } from 'app/services/PlayAlongService/usePlayAlong';
import { selectSettings, settingsActions } from 'app/services/SettingsService';

import { MelodyScaleOptimization } from 'app/components/MelodyScaleOptimization';
import {
  GuitarPracticeInput,
  useGuitarPractice,
} from 'app/components/PlayAlong/GuitarPracticeInput';
import { GuitarRoll, GuitarTuning } from 'app/components/PlayAlong/GuitarRoll';
import { KeyboardRoll } from 'app/components/PlayAlong/KeyboardRoll';
import { PianoRoll } from 'app/components/PlayAlong/PianoRoll';
import { RecallPrompt } from 'app/components/PlayAlong/RecallPrompt';
import { SessionSettings } from 'app/components/PlayAlong/SessionSettings';

import { isFormInputTarget } from 'utils/isFormInputTarget';

const formatTime = (ms: number, roundUp = false) => {
  const seconds = Math.max(0, (roundUp ? Math.ceil : Math.floor)(ms / 1000));
  return `${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, '0')}`;
};
const noteWord = (count: number) => (count === 1 ? 'note' : 'notes');
const practiceModes = [
  { value: 'rhythm', label: 'In time', title: 'Play in time.' },
  { value: 'wait', label: 'Wait mode', title: 'Wait for the correct note.' },
  {
    value: 'repeat',
    label: 'Listen & repeat',
    title: 'Listen to each phrase, then repeat it.',
  },
  {
    value: 'memory',
    label: 'From memory',
    title: 'Play the melody without note hints.',
  },
] as const;

export const PlayAlongPage = () => {
  const { songId } = useParams();
  const library = useSelector(selectLibraryMelodies).filter(
    melody => melody.notes.length,
  );
  const { melody: recording } = useSelector(selectNotes);
  const selected =
    songId === 'recording'
      ? recording
      : songId
      ? library.find(melody => melody.title === songId)
      : library.find(
          melody => (melody.displayTitle ?? melody.title) === 'Ode to Joy',
        ) || library[0];
  useRememberMelodyOpened(songId === 'recording' ? undefined : selected?.title);
  return selected?.notes.length ? (
    <PlayAlongSession
      key={songId || 'default'}
      melody={selected}
      source={{ type: 'melody', recording, library }}
    />
  ) : (
    <Page aria-label="Play Along">
      <BackLink to="/melodies">← Melodies</BackLink>
      <h2>Melody unavailable</h2>
      <p>
        {songId === 'recording'
          ? 'Record a melody in Melody Studio first.'
          : 'Choose another melody from the library.'}
      </p>
      <BackLink to="/sandbox/staff">Open Melody Studio</BackLink>
    </Page>
  );
};

type SessionSource =
  | { type: 'melody'; recording: Melody; library: Melody[] }
  | {
      type: 'routine';
      intro: ReactNode;
      player: 'tabs' | 'guitar';
      speed: number;
      onSpeed: (speed: number) => void;
      guideSound: boolean;
      onGuideSound: (enabled: boolean) => void;
    };

export const PlayAlongSession = ({
  melody,
  source,
}: {
  melody: Melody;
  source: SessionSource;
}) => {
  const routine = source.type === 'routine' ? source : undefined;
  const tabPlayer = routine?.player === 'tabs';
  const startMode = tabPlayer ? 'listen' : 'practice';
  const isRecordingMelody =
    source.type === 'melody' && melody === source.recording;
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const [params, setParams] = useSearchParams();
  const guitarRequested = !routine && params.get('view') === 'guitar';
  const settings = useSelector(selectSettings);
  const recordingProject = useSelector(selectNotes).project;
  useActivateMelody(
    routine ? undefined : melody,
    isRecordingMelody
      ? getRecordingContext(recordingProject)
      : `library:${melody.title}`,
    !isRecordingMelody,
  );
  const originalBpm = useMemo(() => getMelodyBpm(melody), [melody]);
  const speed = routine?.speed ?? settings.bpm / originalBpm;
  const selectedSpeed =
    routine?.speed ??
    [0.5, 0.75, 1, 1.25].find(
      value =>
        originalBpm * value >= 40 &&
        originalBpm * value <= 220 &&
        clampTempo(originalBpm * value) === settings.bpm,
    ) ??
    speed;
  const speeds = Array.from(new Set([0.5, 0.75, 1, 1.25, selectedSpeed])).sort(
    (a, b) => a - b,
  );
  const [practiceMode, setPracticeMode] = useState<PracticeMode>(() => {
    const saved = localStorage.getItem('playAlongPracticeMode');
    return saved === 'rhythm' ||
      (!routine && (saved === 'repeat' || saved === 'memory'))
      ? saved
      : 'wait';
  });
  const [savedView, setView] = useState<'keyboard' | 'piano' | 'guitar'>(() => {
    const saved = localStorage.getItem('playAlongView');
    return saved === 'piano' || saved === 'guitar' ? saved : 'keyboard';
  });
  const view = routine || guitarRequested ? 'guitar' : savedView;
  const [savedTuning, setTuning] = useState<GuitarTuning>(() =>
    localStorage.getItem('playAlongGuitarTuning') === 'guitarDropD'
      ? 'guitarDropD'
      : 'guitar',
  );
  const tuning = routine ? 'guitar' : savedTuning;
  const [hitWindow, setHitWindow] = useState(() => {
    const saved = Number(localStorage.getItem('playAlongTimingTolerance'));
    return TIMING_TOLERANCES.includes(saved) ? saved : HIT_WINDOW;
  });
  const [muteWrongNotes, setMuteWrongNotes] = useState(
    () => localStorage.getItem('playAlongMuteWrongNotes') !== 'false',
  );
  const game = usePlayAlong(
    melody,
    speed,
    practiceMode,
    hitWindow,
    muteWrongNotes,
    tabPlayer ? 'none' : view === 'guitar' ? 'guitar' : 'keys',
    routine && { sound: routine.guideSound, timbre: melody.timbre },
  );
  const guitarInput = useGuitarPractice(
    view === 'guitar' && !tabPlayer,
    game.onGuitarFrame,
    game.pause,
  );
  const canStart = tabPlayer || view !== 'guitar' || guitarInput.available;
  const startSession = () => {
    if (canStart) void game.start(startMode);
  };
  const stats = getSessionStats(game.session);
  const playing = game.status === 'playing';
  const listening = game.mode === 'listen';
  const recallMode = isRecallMode(practiceMode);
  const hideCues = recallMode && !listening;
  const answers = playing ? game.recall?.answers : undefined;
  const locked = playing || game.status === 'paused' || game.loading;
  const bindings = getNoteBindings(settings);
  const keyboardRows = getKeyboardLayout(melody.notes, settings).rows;
  const unmapped = new Set(
    melody.notes
      .filter(({ note }) => !bindings.has(note))
      .map(({ note }) => note),
  ).size;

  useEffect(() => {
    stopMelody();
    batch(() => {
      if (settings.isRecording) {
        dispatch(notesActions.finishRecording());
        dispatch(settingsActions.toggleRecording());
      }
    });
    // Apply the recording's setup once; live input keeps the app's own mapping.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [dispatch, melody]);

  const { loading, mode, status: playbackStatus, start, pause } = game;
  useEffect(() => {
    const onKeyDown = (event: KeyboardEvent) => {
      if (
        event.code !== 'Space' ||
        event.defaultPrevented ||
        event.isComposing ||
        event.metaKey ||
        event.ctrlKey ||
        event.altKey ||
        event.shiftKey ||
        isFormInputTarget(event.target) ||
        (event.target instanceof Element &&
          event.target.closest(
            'button:not([data-session-playback]), a, [role="button"]',
          ))
      )
        return;

      event.preventDefault();
      if (event.repeat || loading) return;
      if (playbackStatus === 'playing') pause();
      else if (canStart || (playbackStatus === 'paused' && mode === 'listen'))
        start(playbackStatus === 'paused' ? mode : startMode);
    };
    window.addEventListener('keydown', onKeyDown);
    return () => window.removeEventListener('keydown', onKeyDown);
  }, [canStart, loading, mode, pause, playbackStatus, start, startMode]);

  const feedback = game.session.feedback;
  const feedbackVisible = feedback && game.elapsed - feedback.at < 750 * speed;
  const counting = playing && game.elapsed < 0;
  const showOverlay = !playing;
  const playLabel = playing
    ? 'Pause'
    : game.status === 'paused'
    ? 'Resume'
    : tabPlayer
    ? game.status === 'finished'
      ? 'Replay tabs'
      : 'Play tabs'
    : game.status === 'finished'
    ? 'Try again'
    : 'Start playing';
  const status = game.loading
    ? 'Loading sound'
    : game.status === 'paused'
    ? 'Pause'
    : counting
    ? 'Get ready'
    : playing
    ? tabPlayer
      ? 'Playing tabs'
      : listening
      ? 'Listening'
      : game.waiting
      ? view === 'guitar'
        ? 'Waiting for guitar note'
        : 'Waiting for key'
      : 'Playing'
    : game.status === 'finished'
    ? 'Done'
    : 'Ready to play';

  const overlay = showOverlay && (
    <Overlay data-testid="play-along-overlay">
      {game.status === 'finished' ? (
        <>
          <h3>
            {routine
              ? 'Exercise complete'
              : listening
              ? 'Your turn'
              : 'Melody complete'}
          </h3>
          <p>
            {tabPlayer
              ? 'Replay this exercise at the same speed or pick another one.'
              : listening
              ? recallMode
                ? 'Start when you’re ready to play.'
                : 'Follow the falling notes to play the melody.'
              : `Hits ${stats.hits}/${melody.notes.length} · best streak ${game.session.bestCombo}`}
          </p>
          {!listening && (
            <ResultDetails>
              <span>
                {practiceMode === 'rhythm' ? 'Perfect' : 'Correct'}{' '}
                <b>{stats.perfect}</b>
              </span>
              {practiceMode === 'rhythm' && (
                <span>
                  Good <b>{stats.good}</b>
                </span>
              )}
              {practiceMode === 'rhythm' && (
                <span>
                  Misses <b>{stats.missed}</b>
                </span>
              )}
              <span>
                Extra <b>{game.session.wrongNotes}</b>
              </span>
            </ResultDetails>
          )}
          <PrimaryButton disabled={!canStart} onClick={startSession}>
            {tabPlayer
              ? 'Replay tabs'
              : listening
              ? 'Start playing'
              : 'Try again'}
          </PrimaryButton>
        </>
      ) : game.status === 'paused' ? (
        <>
          <h3>Pause</h3>
          <p>Continue from where you left off.</p>
          <PrimaryButton
            disabled={game.mode === 'practice' && !canStart}
            onClick={() => game.start(game.mode)}
          >
            Resume
          </PrimaryButton>
        </>
      ) : (
        <>
          <OverlayLabel>
            {practiceMode === 'repeat'
              ? 'LISTEN & REPEAT'
              : practiceMode === 'memory'
              ? 'FROM MEMORY'
              : 'FOLLOW THE NOTES'}
          </OverlayLabel>
          <h3>{melody.displayTitle || melody.title || 'My recording'}</h3>
          {recallMode ? (
            <p>
              {practiceMode === 'repeat'
                ? 'Listen to each phrase, then repeat it at your own pace.'
                : 'Play at your own pace. Each note you play is marked as correct or wrong.'}
            </p>
          ) : (
            <p>
              {view === 'guitar'
                ? 'Play your guitar when the fret number crosses the line.'
                : view === 'keyboard'
                ? 'Press the key when the falling button lines up with it.'
                : 'Press the key when the note reaches the line.'}
              <br />
              {tabPlayer
                ? 'The tabs scroll at the selected rate.'
                : practiceMode === 'wait'
                ? routine
                  ? 'The exercise waits for the right note.'
                  : 'Play the note or full chord to continue.'
                : `You can ${
                    view === 'guitar' ? 'play' : 'press'
                  } up to ${hitWindow} ms early or late.`}
            </p>
          )}
          <PrimaryButton
            disabled={game.loading || !canStart}
            onClick={startSession}
          >
            {game.loading
              ? 'Loading…'
              : !canStart
              ? 'Connect your guitar'
              : playLabel}
          </PrimaryButton>
        </>
      )}
    </Overlay>
  );
  const stageContent =
    playing && game.recall ? (
      <RecallPrompt
        {...game.recall}
        phraseCount={game.phraseCount}
        onReplay={game.replayPhrase}
      />
    ) : (
      overlay
    );

  return (
    <Page
      aria-label={routine ? 'Guitar Practice Routine' : 'Play Along'}
      $guitar={view === 'guitar'}
      $routine={!!routine}
    >
      {routine?.intro}
      <Toolbar aria-label="Practice controls" $wrap={!!routine}>
        <LibraryLink to="/melodies">← Melodies</LibraryLink>
        {source.type === 'melody' && (
          <SongField>
            <select
              aria-label="Melody"
              title={[melody.author, melody.displayTitle ?? melody.title]
                .filter(Boolean)
                .join(' · ')}
              disabled={game.loading}
              value={isRecordingMelody ? 'recording' : melody.title}
              onChange={event =>
                navigate(
                  `/play-along/${encodeURIComponent(event.target.value)}${
                    guitarRequested ? '?view=guitar' : ''
                  }`,
                )
              }
            >
              {source.recording.notes.length > 0 && (
                <option value="recording">My recording</option>
              )}
              {source.library.map(song => (
                <option key={song.title} value={song.title}>
                  {song.displayTitle ?? song.title}
                </option>
              ))}
            </select>
          </SongField>
        )}
        <Actions>
          <PrimaryButton
            data-session-playback
            aria-keyshortcuts="Space"
            title={`${playLabel} (Space)`}
            disabled={
              game.loading ||
              (!playing &&
                !(game.status === 'paused' && listening) &&
                !canStart)
            }
            onClick={() =>
              playing
                ? game.pause()
                : game.start(game.status === 'paused' ? game.mode : startMode)
            }
          >
            {playLabel}
          </PrimaryButton>
          {!routine && (
            <IconButton
              aria-label="Preview"
              title="Preview"
              disabled={game.loading || locked}
              onClick={() => game.start('listen')}
            >
              <ControlIcon name="listen" />
            </IconButton>
          )}
          <IconButton aria-label="Restart" title="Restart" onClick={game.reset}>
            <ControlIcon name="reset" />
          </IconButton>
        </Actions>
        <ControlGroup role="group" aria-label="Rate" data-session-control>
          <ControlLabel>Rate</ControlLabel>
          <Segments>
            {speeds.map(value => (
              <Segment
                type="button"
                key={value}
                aria-pressed={value === selectedSpeed}
                title={
                  value === 1
                    ? 'Original speed'
                    : `Rate ${Number(value.toFixed(2))}×`
                }
                disabled={originalBpm * value < 40 || originalBpm * value > 220}
                onClick={() => {
                  if (routine) routine.onSpeed(value);
                  else
                    dispatch(
                      settingsActions.setBpm(clampTempo(originalBpm * value)),
                    );
                }}
              >
                {Number(value.toFixed(2))}×
              </Segment>
            ))}
          </Segments>
        </ControlGroup>
        {tabPlayer && routine && (
          <GuideControl>
            <input
              type="checkbox"
              checked={routine.guideSound}
              disabled={locked}
              onChange={event => routine.onGuideSound(event.target.checked)}
            />
            Guide sound
          </GuideControl>
        )}
        {!tabPlayer && (
          <>
            <ControlGroup
              role="group"
              aria-label="Practice mode"
              data-session-control
            >
              <Segments>
                {practiceModes
                  .filter(mode => !routine || !isRecallMode(mode.value))
                  .map(mode => (
                    <Segment
                      type="button"
                      key={mode.value}
                      aria-pressed={practiceMode === mode.value}
                      disabled={locked}
                      title={`${mode.title} Reset your attempt to change modes.`}
                      onClick={() => {
                        setPracticeMode(mode.value);
                        localStorage.setItem(
                          'playAlongPracticeMode',
                          mode.value,
                        );
                      }}
                    >
                      {mode.label}
                    </Segment>
                  ))}
              </Segments>
            </ControlGroup>
            {!recallMode && (
              <ControlGroup
                role="group"
                aria-label="Key press tolerance"
                data-session-control
              >
                <ControlLabel>Tolerance</ControlLabel>
                <Segments>
                  {TIMING_TOLERANCES.map(value => (
                    <Segment
                      type="button"
                      key={value}
                      aria-label={`±${value} ms`}
                      aria-pressed={hitWindow === value}
                      disabled={locked}
                      title={`You can press up to ${value} ms early or late. Reset your attempt to change tolerance.`}
                      onClick={() => {
                        setHitWindow(value);
                        localStorage.setItem(
                          'playAlongTimingTolerance',
                          String(value),
                        );
                      }}
                    >
                      ±{value}
                    </Segment>
                  ))}
                </Segments>
                <ControlLabel>ms</ControlLabel>
              </ControlGroup>
            )}
          </>
        )}
        {view !== 'guitar' && (
          <ControlGroup
            role="group"
            aria-label="Wrong-note sound"
            data-session-control
          >
            <ControlLabel>Wrong-note sound</ControlLabel>
            <Segments>
              {[true, false].map(muted => (
                <Segment
                  type="button"
                  key={String(muted)}
                  aria-pressed={muteWrongNotes === muted}
                  title={
                    muted
                      ? 'Play only correct key presses'
                      : 'Play all key presses, including mistakes'
                  }
                  onClick={() => {
                    setMuteWrongNotes(muted);
                    localStorage.setItem(
                      'playAlongMuteWrongNotes',
                      String(muted),
                    );
                  }}
                >
                  {muted ? 'Off' : 'On'}
                </Segment>
              ))}
            </Segments>
          </ControlGroup>
        )}
        {!routine && (
          <ControlGroup role="group" aria-label="Display" data-session-control>
            <Segments>
              {(['keyboard', 'piano', 'guitar'] as const).map(value => (
                <Segment
                  type="button"
                  key={value}
                  aria-label={
                    value === 'guitar'
                      ? 'Guitar'
                      : value === 'keyboard'
                      ? 'Keyboard'
                      : 'Piano'
                  }
                  title={
                    value === 'guitar'
                      ? 'Guitar'
                      : value === 'keyboard'
                      ? 'Keyboard'
                      : 'Piano'
                  }
                  disabled={
                    locked &&
                    (value === 'guitar' || view === 'guitar') &&
                    value !== view
                  }
                  aria-pressed={view === value}
                  onClick={() => {
                    setView(value);
                    localStorage.setItem('playAlongView', value);
                    if (guitarRequested && value !== 'guitar') {
                      const next = new URLSearchParams(params);
                      next.delete('view');
                      setParams(next, { replace: true });
                    }
                  }}
                >
                  <ControlIcon name={value} />
                </Segment>
              ))}
            </Segments>
          </ControlGroup>
        )}
      </Toolbar>
      {view === 'guitar' && !tabPlayer && (
        <GuitarPracticeInput
          input={guitarInput}
          tuning={tuning}
          locked={locked}
          onTuning={
            routine
              ? undefined
              : value => {
                  setTuning(value);
                  localStorage.setItem('playAlongGuitarTuning', value);
                }
          }
        />
      )}
      {!routine && (
        <>
          <SessionSettings />
          <MelodyScaleOptimization
            melody={melody}
            recording={isRecordingMelody}
            disabled={locked}
            onStop={game.reset}
          />
        </>
      )}
      {game.error && <Notice role="alert">{game.error}</Notice>}
      <Scoreboard
        aria-label={tabPlayer ? 'Playback timeline' : 'Practice results'}
        $showScore={!tabPlayer}
        $routine={!!routine}
      >
        {!tabPlayer && (
          <>
            <Metric>
              <span>SCORE</span>
              <strong>{game.session.score.toLocaleString('en')}</strong>
            </Metric>
            <Metric>
              <span>
                {practiceMode === 'wait' ? 'CORRECT NOTES' : 'ACCURACY'}
              </span>
              <strong>
                {stats.accuracy === null ? '…' : `${stats.accuracy}%`}
              </strong>
            </Metric>
            <Metric>
              <span>STREAK</span>
              <strong>
                {game.session.combo}
                <small> {noteWord(game.session.combo)}</small>
              </strong>
            </Metric>
          </>
        )}
        <Timeline>
          <span>
            {counting ? (
              <Countdown
                role="timer"
                aria-label="Countdown"
                aria-live="polite"
                aria-atomic="true"
                title={listening ? 'Get ready to listen' : 'Get ready to play'}
              >
                <span>Starting in</span>
                <strong>
                  {Math.min(
                    LEAD_IN / 1000,
                    Math.ceil(-game.elapsed / (1000 * speed)),
                  )}
                </strong>
              </Countdown>
            ) : (
              <Status>
                <StatusDot $active={playing} />
                {status}
              </Status>
            )}
            {hideCues ? (
              <span>
                {stats.hits} / {melody.notes.length} notes
              </span>
            ) : (
              <time>
                {formatTime(game.elapsed / speed)} /{' '}
                {formatTime(game.duration / speed, true)}
              </time>
            )}
          </span>
          <Progress
            aria-label={routine ? 'Exercise progress' : 'Melody progress'}
            max={hideCues ? melody.notes.length : game.duration}
            value={
              hideCues
                ? stats.hits
                : Math.max(0, Math.min(game.duration, game.elapsed))
            }
          />
        </Timeline>
      </Scoreboard>

      <Stage aria-label="Practice area">
        {view === 'keyboard' ? (
          <KeyboardRoll
            melody={melody}
            elapsed={game.elapsed}
            speed={speed}
            session={game.session}
            listening={listening && playing}
            playing={playing}
            expectedNotes={game.waitingNotes}
            hideCues={hideCues}
            answers={answers}
          >
            {stageContent}
          </KeyboardRoll>
        ) : view === 'guitar' ? (
          <GuitarRoll
            melody={melody}
            tuning={tuning}
            elapsed={game.elapsed}
            speed={speed}
            session={game.session}
            listening={listening && playing}
            sounding={guitarInput.sounding}
            showDetection={!tabPlayer}
            hideCues={hideCues}
          >
            {stageContent}
          </GuitarRoll>
        ) : (
          <PianoRoll
            melody={melody}
            elapsed={game.elapsed}
            speed={speed}
            session={game.session}
            listening={listening && playing}
            playing={playing}
            expectedNotes={game.waitingNotes}
            hideCues={hideCues}
            answers={answers}
          >
            {stageContent}
          </PianoRoll>
        )}
        {game.waiting && (
          <WaitPrompt role="status" aria-live="polite">
            <span>
              {view === 'guitar'
                ? 'Play'
                : feedback?.text === 'Wrong key'
                ? 'Try'
                : 'Press'}
            </span>
            {game.waitingNotes.map((note, i) => {
              const key = bindings.get(note);
              const color = keyboardRows
                .flatMap(row => row.targets)
                .find(target => target.note === note)?.color;
              return (
                <kbd
                  key={`${note}-${i}`}
                  style={
                    view === 'keyboard' && color
                      ? { borderColor: color, background: color }
                      : undefined
                  }
                >
                  {view === 'guitar'
                    ? ''
                    : key
                    ? keyboardButtons[key].title || 'Space'
                    : 'Screen'}{' '}
                  <small>{note}</small>
                </kbd>
              );
            })}
          </WaitPrompt>
        )}
        {!tabPlayer && !hideCues && playing && !counting && !game.waiting && (
          <Feedback
            $keyboard={view === 'keyboard'}
            aria-live="polite"
            $positive={
              feedback?.text === 'Perfect!' ||
              feedback?.text === 'Good' ||
              feedback?.text === 'Correct'
            }
          >
            {listening
              ? view === 'keyboard'
                ? 'Guide'
                : view === 'guitar'
                ? 'Listen and follow the tablature'
                : 'Listen and follow the keys'
              : feedbackVisible
              ? view === 'guitar' && feedback.text === 'Wrong key'
                ? 'Wrong note'
                : feedback.text
              : ''}
          </Feedback>
        )}
      </Stage>
      {unmapped > 0 && view !== 'guitar' && (
        <Notice>
          {unmapped} {noteWord(unmapped)}{' '}
          {noteWord(unmapped) === 'note' ? 'unavailable' : 'unavailable'} in
          this layout.{' '}
          {view === 'keyboard'
            ? 'They appear in a separate on-screen row.'
            : 'Play them on the on-screen piano.'}{' '}
        </Notice>
      )}
    </Page>
  );
};

