import { InstrumentEffects, LIVE_INPUT_EFFECTS_KEY } from './settings';

export const cursorWahFrequency = (frequency: number, offset: number) =>
  Math.max(250, Math.min(2500, frequency * Math.pow(10, offset)));

export interface CursorWahTarget {
  key: string;
  frequency: number;
  continuous: boolean;
}

type Source = {
  move: (offset: number) => void;
  target?: CursorWahTarget;
};
const sources = new Map<string, Set<Source>>();
const targets = new Map<string, CursorWahTarget>();
const positions = new Map<string, number>();
const listeners = new Set<() => void>();

const publish = (key: string) => {
  const active = Array.from(sources.get(key) ?? []).flatMap(source =>
    source.target ? [source.target] : [],
  );
  const previous = targets.get(key);
  const next = active.length
    ? { ...active[0], continuous: active.some(target => target.continuous) }
    : undefined;
  if (
    previous?.frequency === next?.frequency &&
    previous?.continuous === next?.continuous
  )
    return;
  if (next) targets.set(key, next);
  else targets.delete(key);
  listeners.forEach(listener => listener());
};

// Only realtime racks register here. Offline exports never follow live gestures.
export const registerCursorWah = (
  key: string,
  move: Source['move'],
  continuous = false,
) => {
  const source: Source = { move };
  const group = sources.get(key) ?? new Set<Source>();
  group.add(source);
  sources.set(key, group);
  move(positions.get(key) ?? 0);
  return {
    update(settings: InstrumentEffects) {
      const stage = [
        settings,
        ...(settings.pedals ?? [])
          .filter(pedal => pedal.enabled)
          .flatMap(pedal => pedal.stages),
      ].find(
        stage =>
          stage.wah.enabled && (stage.wahMode ?? settings.wahMode) === 'cursor',
      );
      source.target =
        !settings.bypass && stage
          ? { key, frequency: stage.wah.frequency, continuous }
          : undefined;
      publish(key);
    },
    dispose() {
      group.delete(source);
      if (!group.size) {
        sources.delete(key);
        positions.delete(key);
      }
      publish(key);
    },
  };
};

export const moveCursorWah = (key: string, value: number) => {
  if (!sources.has(key)) return;
  const offset = Number.isFinite(value) ? Math.max(-1, Math.min(1, value)) : 0;
  positions.set(key, offset);
  sources.get(key)?.forEach(source => source.move(offset));
};

export const getCursorWahTarget = (timbre: string) =>
  targets.get(timbre) ?? targets.get(LIVE_INPUT_EFFECTS_KEY);

export const subscribeCursorWah = (listener: () => void) => {
  listeners.add(listener);
  return () => {
    listeners.delete(listener);
  };
};
