import { useEffect, useId, useRef, useState } from 'react';
import styled from 'styled-components';

import { wahPedalPreset } from 'app/services/EffectsService/presetCatalog';
import {
  EffectPreset,
  builtInEffectPresets,
  togglePresetPedal,
} from 'app/services/EffectsService/presets';
import {
  EffectStage,
  InstrumentEffects,
  MAX_PEDALS,
  PresetPedal,
  defaultEffects,
  effectDefinitions,
  effectNames,
  toEffectStage,
} from 'app/services/EffectsService/settings';

import { EffectPedalCard } from './EffectPedalCard';
import type { EffectsDialogElement } from './EffectsDialog';
import { PedalCatalogDialog } from './PedalCatalogDialog';
import { WahControl } from './WahControl';

const legacyWahId = 'fixed-mixer-wah';
const cleanSettings = defaultEffects('');

type PedalDrag = {
  pointer: number;
  from: number;
  startX: number;
  startScroll: number;
  x: number;
  y: number;
  active: boolean;
};

export const PresetPedalboard = ({
  settings,
  onChange,
  customPresets,
}: {
  settings: InstrumentEffects;
  onChange: (settings: InstrumentEffects) => void;
  customPresets: EffectPreset[];
}) => {
  const chainPedals = settings.pedals ?? [];
  // Existing mixer Wah stays in its original signal position, before drive.
  const hasLegacyWah =
    settings.wahMode === 'cursor' ||
    settings.wah.enabled ||
    effectDefinitions.wah.controls.some(
      ({ key }) =>
        settings.wah[key as keyof typeof settings.wah] !==
        cleanSettings.wah[key as keyof typeof settings.wah],
    );
  const pedals = hasLegacyWah
    ? [
        {
          id: legacyWahId,
          presetId: wahPedalPreset.id,
          name: 'Wah (original position)',
          enabled: settings.wah.enabled,
          stages: [
            {
              ...toEffectStage(cleanSettings),
              wah: { ...settings.wah, enabled: true },
              wahMode: settings.wahMode,
            },
          ],
        },
        ...chainPedals,
      ]
    : chainPedals;
  const [editing, setEditing] = useState('');
  const [stageIndex, setStageIndex] = useState(0);
  const catalogId = useId();
  const catalog = useRef<EffectsDialogElement>(null);
  const addPedal = useRef<HTMLButtonElement>(null);
  const chain = useRef<HTMLDivElement>(null);
  const drag = useRef<PedalDrag>();
  const frame = useRef(0);
  const suppressClick = useRef(false);
  const [preview, setPreview] = useState<{
    from: number;
    to: number;
    offset: number;
  }>();
  const [announcement, setAnnouncement] = useState('');
  useEffect(() => () => cancelAnimationFrame(frame.current), []);
  const replace = (next: PresetPedal[]) => {
    const legacy = next.find(pedal => pedal.id === legacyWahId);
    onChange({
      ...settings,
      ...(hasLegacyWah && {
        wah: legacy
          ? { ...legacy.stages[0].wah, enabled: legacy.enabled }
          : cleanSettings.wah,
        wahMode: legacy?.stages[0].wahMode ?? 'auto',
      }),
      pedals: next.filter(pedal => pedal.id !== legacyWahId),
    });
  };
  const edited = pedals.find(item => item.id === editing);
  const stage = edited?.stages[stageIndex];
  const updateStage = (nextStage: EffectStage) =>
    replace(
      pedals.map(pedal =>
        pedal.id !== editing
          ? pedal
          : {
              ...pedal,
              stages: pedal.stages.map((item, index) =>
                index === stageIndex ? nextStage : item,
              ),
            },
      ),
    );
  const move = (from: number, to: number) => {
    const firstMovable = Number(hasLegacyWah);
    if (
      from === to ||
      from < firstMovable ||
      to < firstMovable ||
      to >= pedals.length
    )
      return;
    const next = [...pedals];
    const [pedal] = next.splice(from, 1);
    next.splice(to, 0, pedal);
    replace(next);
    setAnnouncement(`${pedal.name} moved to position ${to + 1}.`);
  };
  const dragPosition = (gesture: PedalDrag, board: HTMLDivElement) => {
    const slots = Array.from(
      board.querySelectorAll<HTMLElement>('[data-pedal-slot]'),
    );
    const source = slots[gesture.from];
    const offset = Math.max(
      slots[Number(hasLegacyWah)].offsetLeft - source.offsetLeft,
      Math.min(
        slots[slots.length - 1].offsetLeft - source.offsetLeft,
        gesture.x - gesture.startX + board.scrollLeft - gesture.startScroll,
      ),
    );
    const center = source.offsetLeft + source.offsetWidth / 2 + offset;
    const to = slots.reduce((nearest, slot, index) => {
      const distance = (element: HTMLElement) =>
        Math.abs(center - element.offsetLeft - element.offsetWidth / 2);
      return index >= Number(hasLegacyWah) &&
        distance(slot) < distance(slots[nearest])
        ? index
        : nearest;
    }, gesture.from);
    return { from: gesture.from, to, offset };
  };
  const scrollWhileDragging = () => {
    const gesture = drag.current;
    const board = chain.current;
    if (!gesture?.active || !board) return;
    const bounds = board.getBoundingClientRect();
    const before = board.scrollLeft;
    if (gesture.y >= bounds.top && gesture.y <= bounds.bottom) {
      if (gesture.x <= bounds.left + 28) board.scrollLeft -= 10;
      if (gesture.x >= bounds.right - 28) board.scrollLeft += 10;
    }
    if (board.scrollLeft !== before) setPreview(dragPosition(gesture, board));
    frame.current = requestAnimationFrame(scrollWhileDragging);
  };
  const finishDrag = (pointer: number, drop?: { x: number; y: number }) => {
    const gesture = drag.current;
    if (gesture?.pointer !== pointer) return;
    drag.current = undefined;
    cancelAnimationFrame(frame.current);
    setPreview(undefined);
    const board = chain.current;
    if (!gesture.active || !drop || !board) return;
    const bounds = board.getBoundingClientRect();
    if (
      drop.x < bounds.left ||
      drop.x > bounds.right ||
      drop.y < bounds.top ||
      drop.y > bounds.bottom
    )
      return;
    move(gesture.from, dragPosition({ ...gesture, ...drop }, board).to);
  };
  return (
    <Board aria-label="Preset pedalboard">
      <Heading>
        <strong>Pedalboard</strong>
        <span>
          {chainPedals.filter(item => item.enabled).length} enabled ·{' '}
          {chainPedals.length} / {MAX_PEDALS}
        </span>
      </Heading>
      <p>
        Sound runs through the faders first, then through the pedals from left
        to right. Click a pedal to switch it on or off. Drag the handle or use
        the arrow keys on a focused pedal to change its position.
      </p>
      <ReorderStatus role="status">{announcement}</ReorderStatus>
      <Chain
        ref={chain}
        role="list"
        aria-label="Pedal order"
        onDragStart={event => event.preventDefault()}
      >
        {pedals.map((pedal, index) => (
          <Slot
            key={pedal.id}
            role="listitem"
            data-pedal-slot
            data-dragging={preview?.from === index}
            data-drop-side={
              preview?.to === index && preview.from !== index
                ? preview.from < index
                  ? 'right'
                  : 'left'
                : undefined
            }
            style={
              preview?.from === index
                ? { transform: `translateX(${preview.offset}px)` }
                : undefined
            }
            onPointerDown={event => {
              suppressClick.current = false;
              const target = event.target as Element;
              if (
                pedal.id === legacyWahId ||
                chainPedals.length < 2 ||
                !event.isPrimary ||
                event.button !== 0 ||
                target.closest('[data-pedal-action]') ||
                (event.pointerType === 'touch' &&
                  !target.closest('[data-pedal-grip]')) ||
                !chain.current
              )
                return;
              target.setPointerCapture(event.pointerId);
              drag.current = {
                pointer: event.pointerId,
                from: index,
                startX: event.clientX,
                startScroll: chain.current.scrollLeft,
                x: event.clientX,
                y: event.clientY,
                active: false,
              };
            }}
            onPointerMove={event => {
              const gesture = drag.current;
              if (gesture?.pointer !== event.pointerId || !chain.current)
                return;
              gesture.x = event.clientX;
              gesture.y = event.clientY;
              if (!gesture.active) {
                if (Math.abs(gesture.x - gesture.startX) < 6) return;
                gesture.active = true;
                suppressClick.current = true;
                frame.current = requestAnimationFrame(scrollWhileDragging);
              }
              setPreview(dragPosition(gesture, chain.current));
            }}
            onPointerUp={event =>
              finishDrag(event.pointerId, {
                x: event.clientX,
                y: event.clientY,
              })
            }
            onPointerCancel={event => finishDrag(event.pointerId)}
            onLostPointerCapture={event => finishDrag(event.pointerId)}
            onClickCapture={event => {
              if (suppressClick.current && event.detail > 0) {
                suppressClick.current = false;
                event.stopPropagation();
              }
            }}
            onKeyDown={event => {
              if (event.target !== event.currentTarget.firstElementChild)
                return;
              if (event.key !== 'ArrowLeft' && event.key !== 'ArrowRight')
                return;
              event.preventDefault();
              const control = event.target as HTMLButtonElement;
              move(index, index + (event.key === 'ArrowLeft' ? -1 : 1));
              requestAnimationFrame(() => control.focus());
            }}
          >
            <EffectPedalCard
              id={pedal.presetId}
              name={pedal.name}
              active={pedal.enabled && !settings.bypass}
              pressed={pedal.enabled}
              action={`Pedal ${index + 1}: ${pedal.name}`}
              onToggle={() =>
                replace(
                  pedals.map(item =>
                    item.id === pedal.id
                      ? { ...item, enabled: !item.enabled }
                      : item,
                  ),
                )
              }
            />
            <CardControls>
              <CardAction
                data-pedal-action
                type="button"
                onClick={() => {
                  setEditing(editing === pedal.id ? '' : pedal.id);
                  setStageIndex(0);
                }}
                aria-expanded={editing === pedal.id}
                aria-label={`Configure ${pedal.name}`}
                title={`Configure ${pedal.name}`}
              >
                <svg
                  viewBox="0 0 24 24"
                  aria-hidden="true"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="2"
                  strokeLinecap="round"
                >
                  <path d="M4 6h16M4 12h16M4 18h16M8 4v4m8 2v4m-6 2v4" />
                </svg>
              </CardAction>
              {pedal.id !== legacyWahId && chainPedals.length > 1 && (
                <Grip data-pedal-grip aria-hidden="true" />
              )}
              <CardAction
                data-pedal-action
                type="button"
                aria-label={`Remove ${pedal.name}`}
                title={`Remove ${pedal.name}`}
                onClick={event => {
                  event.currentTarget
                    .closest('[data-pedal-slot]')
                    ?.nextElementSibling?.querySelector('button')
                    ?.focus();
                  replace(pedals.filter(item => item.id !== pedal.id));
                }}
              >
                ×
              </CardAction>
            </CardControls>
          </Slot>
        ))}
        <AddSlot role="listitem">
          <AddPedal
            ref={addPedal}
            type="button"
            aria-label="Add pedal"
            aria-haspopup="dialog"
            aria-controls={catalogId}
            onClick={() => {
              catalog.current?.showModal();
              catalog.current?.querySelector('input')?.focus();
            }}
          >
            +
          </AddPedal>
        </AddSlot>
      </Chain>
      {edited && stage && (
        <Editor aria-label={`Pedal settings ${edited.name}`}>
          <Heading>
            <strong>{edited.name}</strong>
            <button type="button" onClick={() => setEditing('')}>
              Close pedal settings
            </button>
          </Heading>
          {edited.id === legacyWahId && (
            <p>This Wah keeps its original place before distortion.</p>
          )}
          {edited.stages.length > 1 && (
            <label>
              Saved chain stage
              <select
                value={stageIndex}
                onChange={event => setStageIndex(Number(event.target.value))}
              >
                {edited.stages.map((_, index) => (
                  <option key={index} value={index}>
                    Stage {index + 1}
                  </option>
                ))}
              </select>
            </label>
          )}
          <Controls>
            {(edited.presetId === wahPedalPreset.id
              ? (['wah'] as const)
              : effectNames
            ).map(name => {
              const definition = effectDefinitions[name];
              const effect = stage[name];
              const update = (key: string, value: number | boolean) =>
                updateStage({
                  ...stage,
                  [name]: {
                    ...effect,
                    [key]: value,
                    enabled: key === 'enabled' ? Boolean(value) : true,
                  },
                });
              return (
                <fieldset key={name}>
                  <legend>
                    {edited.presetId === wahPedalPreset.id ? (
                      definition.title
                    ) : (
                      <label>
                        <input
                          type="checkbox"
                          checked={effect.enabled}
                          onChange={event =>
                            update('enabled', event.target.checked)
                          }
                        />
                        {definition.title}
                      </label>
                    )}
                  </legend>
                  {name === 'wah' && (
                    <WahControl
                      mode={stage.wahMode ?? settings.wahMode ?? 'auto'}
                      onChange={mode =>
                        updateStage({
                          ...stage,
                          wahMode: mode,
                          wah: { ...stage.wah, enabled: true },
                        })
                      }
                    />
                  )}
                  {definition.controls.map(control => (
                    <label key={control.key}>
                      {control.label}:{' '}
                      {
                        (effect as unknown as Record<string, number>)[
                          control.key
                        ]
                      }{' '}
                      {control.unit}
                      <input
                        type="range"
                        aria-label={`Pedal: ${control.label}`}
                        min={control.min}
                        max={control.max}
                        step={control.step}
                        value={
                          (effect as unknown as Record<string, number>)[
                            control.key
                          ]
                        }
                        onPointerUp={event => event.currentTarget.blur()}
                        onPointerCancel={event => event.currentTarget.blur()}
                        onChange={event =>
                          update(control.key, Number(event.target.value))
                        }
                      />
                    </label>
                  ))}
                </fieldset>
              );
            })}
          </Controls>
        </Editor>
      )}
      <PedalCatalogDialog
        id={catalogId}
        dialog={catalog}
        settings={settings}
        presets={[wahPedalPreset, ...builtInEffectPresets, ...customPresets]}
        onClose={() => addPedal.current?.focus()}
        onSelect={preset => onChange(togglePresetPedal(settings, preset))}
      />
    </Board>
  );
};

const Board = styled.section`
  margin-top: 16px;
  padding-top: 16px;
  border-top: 1px solid ${p => p.theme.border};
  p {
    color: ${p => p.theme.textSecondary};
    line-height: 1.5;
  }
`;
const Heading = styled.div`
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  span {
    color: ${p => p.theme.textSecondary};
  }
`;
const Chain = styled.div`
  position: relative;
  display: flex;
  gap: 20px;
  overflow-x: auto;
  padding: 6px 6px 12px;
  overscroll-behavior-x: contain;
`;
const Slot = styled.div`
  position: relative;
  flex: 0 0 174px;
  min-width: 0;
  user-select: none;
  > button:first-child {
    padding-top: 44px;
  }
  &[data-dragging='true'] {
    z-index: 2;
    opacity: 0.9;
  }
  &[data-drop-side]::after {
    content: '';
    position: absolute;
    inset-block: 0;
    width: 3px;
    border-radius: 3px;
    background: ${p => p.theme.primary};
  }
  &[data-drop-side='left']::after {
    left: -11px;
  }
  &[data-drop-side='right']::after {
    right: -11px;
  }
`;
const AddSlot = styled.div`
  flex: none;
  align-self: center;
`;
const AddPedal = styled.button`
  && {
    width: 52px;
    height: 52px;
    padding: 0;
    font-size: 26px;
    border-style: dashed;
  }
  &&:hover {
    border-color: ${p => p.theme.primary};
    color: ${p => p.theme.primary};
  }
`;
const CardControls = styled.div`
  position: absolute;
  top: 6px;
  left: 6px;
  right: 6px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  pointer-events: none;
`;
const CardAction = styled.button`
  && {
    display: grid;
    place-items: center;
    width: 32px;
    min-height: 32px;
    padding: 0;
    font-size: 20px;
    line-height: 1;
    pointer-events: auto;
  }
  svg {
    width: 17px;
    height: 17px;
  }
`;
const Grip = styled.span`
  display: grid;
  place-items: center;
  width: 42px;
  height: 32px;
  cursor: grab;
  touch-action: none;
  pointer-events: auto;
  &::after {
    content: '';
    width: 22px;
    height: 12px;
    border-radius: 4px;
    background: radial-gradient(circle, currentColor 1px, transparent 1.5px)
      center / 6px 6px;
    color: #101d24;
    background-color: #ffffffb3;
  }
`;
const ReorderStatus = styled.span`
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip-path: inset(50%);
`;
const Editor = styled.section`
  margin: 12px 0;
  padding: 12px;
  background: ${p => p.theme.surface};
  border: 1px solid ${p => p.theme.border};
  border-radius: 8px;
`;
const Controls = styled.div`
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(220px, 100%), 1fr));
  gap: 12px;
  margin-top: 12px;
  fieldset {
    min-width: 0;
    border: 1px solid ${p => p.theme.border};
    border-radius: 6px;
  }
  label {
    margin: 8px 0;
  }
  input[type='checkbox'] {
    width: auto;
    min-height: 0;
  }
  legend label {
    display: inline-flex;
    flex-direction: row;
    align-items: center;
  }
`;
